"""``requirements.lock`` as a dependency-graph snapshot (Q6.4): every pin, direct or not."""
from __future__ import annotations

from pathlib import Path

from helab.dependency_snapshot import CORRELATOR, LOCK, locked, snapshot

ROOT = Path(__file__).resolve().parent.parent

SAMPLE = """\
# This file was autogenerated by uv via the following command:
#    uv pip compile requirements.txt --universal --python-version 3.13 -o requirements.lock
pandas==3.0.6
    # via -r requirements.txt
pillow==13.0.0
    # via
    #   matplotlib
    #   pytablericons
PyQt6_sip==13.10.2
    # via
    #   -r requirements.txt
    #   pyqt6
pywin32==312 ; sys_platform == 'win32'
    # via pyinstaller
"""


def test_the_lock_s_pins_with_markers_and_direct_ones_marked() -> None:
    assert locked(SAMPLE) == {"pandas": ("3.0.6", True), "pillow": ("13.0.0", False),
                              "pyqt6-sip": ("13.10.2", True), "pywin32": ("312", False)}


def test_the_snapshot_names_each_package_by_its_purl() -> None:
    body = snapshot(SAMPLE, "a" * 40, "refs/heads/main", "7", "owner/repo", "2026-10-28T00:00:00+00:00")
    assert body["job"] == {"correlator": CORRELATOR, "id": "7"} and body["sha"] == "a" * 40
    resolved = body["manifests"][LOCK]["resolved"]
    assert resolved["pillow"] == {"package_url": "pkg:pypi/pillow@13.0.0", "relationship": "indirect",
                                  "scope": "runtime"}
    assert resolved["pandas"]["relationship"] == "direct"


def test_the_real_lock_parses_with_every_requirement_direct() -> None:
    text = (ROOT / LOCK).read_text(encoding="utf-8")
    packages = locked(text)
    assert len(packages) == sum(1 for line in text.splitlines() if line[:1].isalnum() and "==" in line)
    wanted = {line.split(";")[0].strip().lower().replace("_", "-") for line in (ROOT / "requirements.txt").read_text().splitlines()
              if line.strip() and not line.startswith("#")}
    assert {name for name, (_, direct) in packages.items() if direct} == wanted
